func TestGitPublisherPublishesExactCandidateAndReplays(t *testing.T) {
	root, remote, base, candidate := gitFixture(t)
	publisher, err := NewGitCommandPublisher(root, "origin", "main")
	if err != nil {
		t.Fatal(err)
	}
	head, err := publisher.BaseHead(t.Context())
	if err != nil || head != base {
		t.Fatalf("base head = %q, %v", head, err)
	}
	replay, err := publisher.Publish(t.Context(), "harness/run-1", candidate)
	if err != nil || replay {
		t.Fatalf("publish replay=%v err=%v", replay, err)
	}
	replay, err = publisher.Publish(t.Context(), "harness/run-1", candidate)
	if err != nil || !replay {
		t.Fatalf("retry replay=%v err=%v", replay, err)
	}
	got := gitOutput(t, remote, "rev-parse", "refs/heads/harness/run-1")
	if got != candidate {
		t.Fatalf("published head = %s", got)
	}
}

func TestGitPublisherRejectsCollisionMissingCandidateAndCancellation(t *testing.T) {
	root, _, _, candidate := gitFixture(t)
	publisher, err := NewGitCommandPublisher(root, "origin", "main")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := publisher.Publish(t.Context(), "harness/collision", candidate); err != nil {
		t.Fatal(err)
	}
	other := gitCommit(t, root, "other.txt", "other")
	runGit(t, root, "push", "--force", "origin", other+":refs/heads/harness/collision")
	if _, err := publisher.Publish(
		t.Context(), "harness/collision", candidate,
	); !errors.Is(err, ErrBranchConflict) {
		t.Fatalf("collision error = %v", err)
	}
	if _, err := publisher.Publish(
		t.Context(), "harness/missing", strings.Repeat("f", 40),
	); !errors.Is(err, ErrInvalidRequest) {
		t.Fatalf("missing candidate error = %v", err)
	}
	ctx, cancel := context.WithCancel(t.Context())
	cancel()
	if _, err := publisher.Publish(
		ctx, "harness/cancelled", other,
	); !errors.Is(err, context.Canceled) {
		t.Fatalf("cancelled publication error = %v", err)
	}
}

func TestGitPublisherDisablesHostileHooksAndPrompts(t *testing.T) {
	root, _, _, candidate := gitFixture(t)
	hooks := filepath.Join(root, ".git", "hooks")
	if err := os.WriteFile(
		filepath.Join(hooks, "pre-push"), []byte("#!/bin/sh\nexit 91\n"), 0o755,
	); err != nil {
		t.Fatal(err)
	}
	publisher, err := NewGitCommandPublisher(root, "origin", "main")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := publisher.Publish(t.Context(), "harness/no-hooks", candidate); err != nil {
		t.Fatalf("hostile hook was executed: %v", err)
	}
}

func gitFixture(t *testing.T) (root, remote, base, candidate string) {
	t.Helper()
	parent := t.TempDir()
	remote = filepath.Join(parent, "remote.git")
	runGit(t, parent, "init", "--bare", remote)
	root = filepath.Join(parent, "source")
	runGit(t, parent, "init", "-b", "main", root)
	runGit(t, root, "config", "user.name", "Publication Test")
	runGit(t, root, "config", "user.email", "publication@example.invalid")
	base = gitCommit(t, root, "base.txt", "base")
	runGit(t, root, "remote", "add", "origin", remote)
	runGit(t, root, "push", "origin", "main:main")
	candidate = gitCommit(t, root, "candidate.txt", "candidate")
	return root, remote, base, candidate
}

func gitCommit(t *testing.T, root, name, contents string) string {
	t.Helper()
	if err := os.WriteFile(filepath.Join(root, name), []byte(contents), 0o600); err != nil {
		t.Fatal(err)
	}
	runGit(t, root, "add", name)
	runGit(t, root, "commit", "-m", name)
	return gitOutput(t, root, "rev-parse", "HEAD")
}

func runGit(t *testing.T, root string, args ...string) {
	t.Helper()
	command := exec.Command("git", args...)
	command.Dir = root
	if output, err := command.CombinedOutput(); err != nil {
		t.Fatalf("git %v: %v\n%s", args, err, output)
	}
}

func gitOutput(t *testing.T, root string, args ...string) string {
	t.Helper()
	command := exec.Command("git", args...)
	command.Dir = root
	output, err := command.Output()
	if err != nil {
		t.Fatalf("git %v: %v", args, err)
	}
	return strings.TrimSpace(string(output))
}
package publication

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/Standard-Syntax/basic/go/internal/workflow"
	"github.com/google/uuid"
)

type Service struct {
	config    Config
	artifacts ArtifactStore
	workflow  WorkflowStore
	git       GitPublisher
	pulls     PullRequestClient
	ledger    PublicationLedger
}

func NewService(
	config Config,
	artifacts ArtifactStore,
	workflowStore WorkflowStore,
	gitPublisher GitPublisher,
	pulls PullRequestClient,
	ledger PublicationLedger,
) (*Service, error) {
	normalized, err := normalizeConfig(config)
	if err != nil {
		return nil, err
	}
	if artifacts == nil || workflowStore == nil || gitPublisher == nil ||
		pulls == nil || ledger == nil {
		return nil, errors.New("publication service ports are required")
	}
	if _, err := uuid.Parse(normalized.ActorID); err != nil {
		return nil, fmt.Errorf("%w: publication actor ID", ErrInvalidRequest)
	}
	return &Service{
		config: normalized, artifacts: artifacts, workflow: workflowStore,
		git: gitPublisher, pulls: pulls, ledger: ledger,
	}, nil
}

func (s *Service) Publish(ctx context.Context, request Request) (Result, error) {
	if err := validateRequestHeader(s.config, request); err != nil {
		return Result{}, err
	}
	inputs, err := validateArtifacts(ctx, s.artifacts, s.config, request)
	if err != nil {
		return Result{}, err
	}
	rendered, err := renderPullRequest(s.config, request, inputs)
	if err != nil {
		return Result{}, err
	}
	digest, err := publicationRequestDigest(request)
	if err != nil {
		return Result{}, err
	}
	handle, err := s.ledger.Begin(ctx, PublicationStart{
		PublicationID: request.PublicationID, RequestDigest: digest,
		RequestedAt: request.PublicationTimestamp,
		Repository:  s.config.RepositoryOwner + "/" + s.config.RepositoryName,
		BaseBranch:  s.config.BaseBranch, HeadBranch: rendered.Head,
		BaseCommit: request.BaseCommit, CandidateCommit: request.CandidateCommit,
		SpecificationDigest:  request.Specification.Digest,
		ImplementationDigest: request.Implementation.Digest,
		ExecutionDigest:      request.Execution.Digest,
		VerificationDigest:   request.Verification.Digest,
		ReviewDigest:         request.Review.Digest, ApprovalDigest: request.Approval.Digest,
		ExpectedRunRevision: request.ExpectedRunRevision,
	})
	if err != nil {
		return Result{}, fmt.Errorf("reserve publication: %w", err)
	}
	if replay, ok := handle.Replay(); ok {
		replay.Replay = true
		return replay, nil
	}
	return s.publishReserved(ctx, request, rendered, handle)
}

func (s *Service) publishReserved(
	ctx context.Context,
	request Request,
	rendered DraftPullRequestInput,
	handle PublicationHandle,
) (Result, error) {
	branch, ready := handle.Branch()
	if !ready {
		head, err := s.git.BaseHead(ctx)
		if err != nil {
			_ = handle.Rollback(ctx)
			return Result{}, fmt.Errorf("inspect publication base: %w", err)
		}
		if head != request.BaseCommit {
			_ = handle.Rollback(ctx)
			return Result{}, ErrBaseDrift
		}
		if _, err := s.git.Publish(ctx, rendered.Head, request.CandidateCommit); err != nil {
			_ = handle.Rollback(ctx)
			return Result{}, err
		}
		branch = BranchCheckpoint{Branch: rendered.Head, CandidateCommit: request.CandidateCommit}
		if err := handle.SaveBranch(ctx, branch); err != nil {
			return Result{}, fmt.Errorf("checkpoint publication branch: %w", err)
		}
	}
	if branch.Branch != rendered.Head || branch.CandidateCommit != request.CandidateCommit {
		return Result{}, ErrPublicationConflict
	}
	checkpoint, ready := handle.PullRequest()
	if !ready {
		head, err := s.git.BaseHead(ctx)
		if err != nil {
			return Result{}, fmt.Errorf("recheck publication base: %w", err)
		}
		if head != request.BaseCommit {
			return Result{}, ErrBaseDrift
		}
		pr, exists, err := s.pulls.FindDraft(ctx, rendered)
		if err != nil {
			return Result{}, fmt.Errorf("find draft pull request: %w", err)
		}
		if !exists {
			pr, err = s.pulls.CreateDraft(ctx, rendered)
			if err != nil {
				recovered, found, findErr := s.pulls.FindDraft(ctx, rendered)
				if findErr != nil || !found {
					return Result{}, fmt.Errorf("create draft pull request: %w", err)
				}
				pr = recovered
			}
		}
		checkpoint = PullRequestCheckpoint{
			Branch: rendered.Head, CandidateCommit: request.CandidateCommit,
			PullRequestNumber: pr.Number, PullRequestURL: pr.URL,
		}
		if err := handle.SavePullRequest(ctx, checkpoint); err != nil {
			return Result{}, fmt.Errorf("checkpoint draft pull request: %w", err)
		}
	}
	return s.complete(ctx, request, checkpoint, handle)
}

func (s *Service) complete(
	ctx context.Context,
	request Request,
	checkpoint PullRequestCheckpoint,
	handle PublicationHandle,
) (Result, error) {
	artifact := DraftPullRequestArtifact{
		SchemaVersion: "1", PublicationID: request.PublicationID,
		PublishedAt:     request.PublicationTimestamp.UTC().Format(time.RFC3339Nano),
		RepositoryOwner: s.config.RepositoryOwner, RepositoryName: s.config.RepositoryName,
		BaseBranch: s.config.BaseBranch, HeadBranch: checkpoint.Branch,
		BaseCommit: request.BaseCommit, CandidateCommit: checkpoint.CandidateCommit,
		PullRequestNumber: checkpoint.PullRequestNumber, PullRequestURL: checkpoint.PullRequestURL,
		Draft: true, Specification: request.Specification, Implementation: request.Implementation,
		Execution: request.Execution, Verification: request.Verification,
		Review: request.Review, Approval: request.Approval,
	}
	body, err := json.Marshal(artifact)
	if err != nil {
		return Result{}, fmt.Errorf("encode publication artifact: %w", err)
	}
	ref, err := s.artifacts.Put(ctx, body)
	if err != nil {
		return Result{}, fmt.Errorf("store publication artifact: %w", err)
	}
	sum := sha256.Sum256(body)
	if err := ref.Validate(); err != nil || ref.Digest != hex.EncodeToString(sum[:]) {
		return Result{}, ErrArtifactIntegrity
	}
	recorded, err := s.workflow.ExecuteRun(ctx, workflow.RecordDraftPullRequest{
		Meta: workflow.CommandEnvelope{
			CommandID:        request.PublicationID,
			Actor:            workflow.Actor{ID: s.config.ActorID, Kind: workflow.ActorPublicationService},
			ExpectedRevision: request.ExpectedRunRevision,
			Timestamp:        request.PublicationTimestamp.UTC(),
			CorrelationID:    request.RunID, CausationID: request.PublicationID,
		},
		ID: request.RunID, CandidateCommit: request.CandidateCommit,
		Approval: request.Approval, Publication: ref,
	})
	if err != nil {
		return Result{}, fmt.Errorf("record draft pull request: %w", err)
	}
	result := Result{
		PublicationID: request.PublicationID, Branch: checkpoint.Branch,
		CandidateCommit:   request.CandidateCommit,
		PullRequestNumber: checkpoint.PullRequestNumber, PullRequestURL: checkpoint.PullRequestURL,
		PublicationArtifact: ref, Replay: recorded.Replay,
	}
	if err := handle.Complete(ctx, result); err != nil {
		return Result{}, fmt.Errorf("complete publication: %w", err)
	}
	return result, nil
}

func publicationRequestDigest(request Request) (string, error) {
	encoded, err := json.Marshal(request)
	if err != nil {
		return "", fmt.Errorf("encode publication request: %w", err)
	}
	sum := sha256.Sum256(encoded)
	return hex.EncodeToString(sum[:]), nil
}

// Package artifact provides the durable, local content-addressed artifact store.
package artifact

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"

	"github.com/Standard-Syntax/basic/go/internal/reasoning/gateway"
	"github.com/Standard-Syntax/basic/go/internal/workflow"
	"github.com/google/uuid"
	"golang.org/x/sys/unix"
)

var (
	ErrInvalidRoot = errors.New("artifact root must be an absolute directory")
	ErrInvalidRef  = errors.New("invalid artifact reference")
	ErrTooLarge    = errors.New("artifact exceeds configured limit")
	ErrIntegrity   = errors.New("artifact integrity check failed")
	ErrUnsafe      = errors.New("unsafe artifact path")
)

var digestPattern = regexp.MustCompile(`^[a-f0-9]{64}$`)

const DefaultMaxBytes int64 = 1 << 20

type Store struct {
	root     *os.File
	maxBytes int64
}

func NewStore(root string, maxBytes int64) (*Store, error) {
	if !filepath.IsAbs(root) || filepath.Clean(root) != root {
		return nil, ErrInvalidRoot
	}
	if maxBytes <= 0 {
		maxBytes = DefaultMaxBytes
	}
	if err := os.MkdirAll(root, 0o700); err != nil {
		return nil, fmt.Errorf("create artifact root: %w", err)
	}
	info, err := os.Lstat(root)
	if err != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
		return nil, ErrInvalidRoot
	}
	fd, err := unix.Open(root, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return nil, ErrInvalidRoot
	}
	return &Store{root: os.NewFile(uintptr(fd), root), maxBytes: maxBytes}, nil
}

func (s *Store) Close() error { return s.root.Close() }

func (s *Store) Put(ctx context.Context, body []byte) (workflow.ArtifactRef, error) {
	if err := ctx.Err(); err != nil {
		return workflow.ArtifactRef{}, err
	}
	if int64(len(body)) > s.maxBytes {
		return workflow.ArtifactRef{}, ErrTooLarge
	}
	sum := sha256.Sum256(body)
	digest := hex.EncodeToString(sum[:])
	ref := workflow.ArtifactRef{URI: "artifact://sha256/" + digest, Digest: digest}
	shard, err := s.openShard(digest[:2], true)
	if err != nil {
		return workflow.ArtifactRef{}, err
	}
	defer shard.Close()
	if exists, err := matchesAt(ctx, int(shard.Fd()), digest, body, s.maxBytes); err != nil {
		return workflow.ArtifactRef{}, err
	} else if exists {
		return ref, nil
	}
	tmpName, err := writeTemporaryAt(int(shard.Fd()), body)
	if err != nil {
		return workflow.ArtifactRef{}, err
	}
	defer func() { _ = unix.Unlinkat(int(shard.Fd()), tmpName, 0) }()
	if err := publishAt(ctx, shard, tmpName, digest, body, s.maxBytes); err != nil {
		return workflow.ArtifactRef{}, err
	}
	return ref, nil
}

func matchesAt(
	ctx context.Context, directory int, digest string, body []byte, limit int64,
) (bool, error) {
	existing, err := readAt(ctx, directory, digest, digest, limit)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	if !bytes.Equal(existing, body) {
		return false, ErrIntegrity
	}
	return true, nil
}

func writeTemporaryAt(directory int, body []byte) (string, error) {
	tmpName := ".tmp-" + uuid.NewString()
	tmpFD, err := unix.Openat(
		directory, tmpName,
		unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_NOFOLLOW|unix.O_CLOEXEC,
		0o600,
	)
	if err != nil {
		return "", fmt.Errorf("create artifact temporary file: %w", err)
	}
	tmp := os.NewFile(uintptr(tmpFD), tmpName)
	cleanup := func() { _ = unix.Unlinkat(directory, tmpName, 0) }
	if _, err := tmp.Write(body); err != nil {
		_ = tmp.Close()
		cleanup()
		return "", fmt.Errorf("write artifact: %w", err)
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		cleanup()
		return "", fmt.Errorf("sync artifact: %w", err)
	}
	if err := tmp.Close(); err != nil {
		cleanup()
		return "", err
	}
	return tmpName, nil
}

func publishAt(
	ctx context.Context, shard *os.File, tmpName, digest string, body []byte, limit int64,
) error {
	if err := unix.Linkat(int(shard.Fd()), tmpName, int(shard.Fd()), digest, 0); err != nil {
		if !errors.Is(err, unix.EEXIST) {
			return fmt.Errorf("publish artifact: %w", err)
		}
		existing, readErr := readAt(ctx, int(shard.Fd()), digest, digest, limit)
		if readErr != nil || !bytes.Equal(existing, body) {
			return ErrIntegrity
		}
	}
	if err := shard.Sync(); err != nil {
		return fmt.Errorf("sync artifact directory: %w", err)
	}
	return nil
}

func (s *Store) Get(ctx context.Context, ref workflow.ArtifactRef) ([]byte, error) {
	return s.GetLimit(ctx, ref, s.maxBytes)
}

func (s *Store) GetLimit(ctx context.Context, ref workflow.ArtifactRef, limit int64) ([]byte, error) {
	if ref.URI != "artifact://sha256/"+ref.Digest || !digestPattern.MatchString(ref.Digest) {
		return nil, ErrInvalidRef
	}
	if limit <= 0 || limit > s.maxBytes {
		return nil, ErrTooLarge
	}
	shard, err := s.openShard(ref.Digest[:2], false)
	if err != nil {
		return nil, err
	}
	defer shard.Close()
	return readAt(ctx, int(shard.Fd()), ref.Digest, ref.Digest, limit)
}

func (s *Store) openShard(name string, create bool) (*os.File, error) {
	if create {
		err := unix.Mkdirat(int(s.root.Fd()), name, 0o700)
		if err != nil && !errors.Is(err, unix.EEXIST) {
			return nil, fmt.Errorf("create artifact shard: %w", err)
		}
	}
	fd, err := unix.Openat(
		int(s.root.Fd()), name,
		unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC,
		0,
	)
	if err != nil {
		if errors.Is(err, unix.ELOOP) || errors.Is(err, unix.ENOTDIR) {
			return nil, ErrUnsafe
		}
		return nil, err
	}
	return os.NewFile(uintptr(fd), name), nil
}

func readAt(ctx context.Context, directory int, name, digest string, limit int64) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	fd, err := unix.Openat(
		directory, name, unix.O_RDONLY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0,
	)
	if err != nil {
		if errors.Is(err, unix.ELOOP) {
			return nil, ErrUnsafe
		}
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() {
		return nil, ErrUnsafe
	}
	if info.Size() > limit {
		return nil, ErrTooLarge
	}
	body, err := io.ReadAll(io.LimitReader(file, limit+1))
	if err != nil {
		return nil, err
	}
	if int64(len(body)) > limit {
		return nil, ErrTooLarge
	}
	sum := sha256.Sum256(body)
	if hex.EncodeToString(sum[:]) != digest {
		return nil, ErrIntegrity
	}
	return body, nil
}

// Publication adapts Store to publication's caller-selected read limit.
type Publication struct{ Store *Store }

func (a Publication) Put(ctx context.Context, body []byte) (workflow.ArtifactRef, error) {
	return a.Store.Put(ctx, body)
}
func (a Publication) Get(ctx context.Context, ref workflow.ArtifactRef, limit int64) ([]byte, error) {
	return a.Store.GetLimit(ctx, ref, limit)
}

// Gateway adapts Store to the reasoning gateway's reference type.
type Gateway struct{ Store *Store }

func (a Gateway) Put(ctx context.Context, body []byte) (gateway.ArtifactReference, error) {
	ref, err := a.Store.Put(ctx, body)
	return gateway.ArtifactReference{URI: ref.URI, SHA256: ref.Digest}, err
}
func (a Gateway) Get(ctx context.Context, ref gateway.ArtifactReference) ([]byte, error) {
	return a.Store.Get(ctx, workflow.ArtifactRef{URI: ref.URI, Digest: ref.SHA256})
}
// Command api-service runs the authenticated user-facing control plane.
package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"syscall"
	"time"

	"github.com/Standard-Syntax/basic/go/internal/approval"
	"github.com/Standard-Syntax/basic/go/internal/artifact"
	"github.com/Standard-Syntax/basic/go/internal/beta"
	"github.com/Standard-Syntax/basic/go/internal/controlapi"
	"github.com/Standard-Syntax/basic/go/internal/publication"
	"github.com/Standard-Syntax/basic/go/internal/runtime"
	"github.com/Standard-Syntax/basic/go/internal/workflow"
	"github.com/jackc/pgx/v5/pgxpool"
)

type config struct {
	Listen           string                 `json:"listen"`
	DatabaseURL      string                 `json:"database_url"`
	ArtifactRoot     string                 `json:"artifact_root"`
	RepositoryRoot   string                 `json:"repository_root"`
	ServiceActorID   string                 `json:"service_actor_id"`
	MaxArtifactBytes int64                  `json:"max_artifact_bytes"`
	MaxBodyBytes     int64                  `json:"max_body_bytes"`
	TrustedChecks    []string               `json:"trusted_checks"`
	Principals       []controlapi.Principal `json:"principals"`
	Publication      *publicationConfig     `json:"publication,omitempty"`
	Policy           beta.Policy            `json:"beta_policy"`
}

type publicationConfig struct {
	RepositoryRoot  string `json:"repository_root"`
	RepositoryOwner string `json:"repository_owner"`
	RepositoryName  string `json:"repository_name"`
	Remote          string `json:"remote"`
	BaseBranch      string `json:"base_branch"`
	BranchPrefix    string `json:"branch_prefix"`
	ActorID         string `json:"actor_id"`
	APIEndpoint     string `json:"api_endpoint"`
	APIVersion      string `json:"api_version"`
	TokenFile       string `json:"token_file"`
}

func main() {
	os.Exit(mainExit())
}

func mainExit() int {
	slog.SetDefault(slog.New(slog.NewJSONHandler(os.Stdout, nil)))
	configPath := flag.String("config", "", "absolute path to strict JSON configuration")
	flag.Parse()
	value, err := loadConfig(*configPath)
	if err != nil {
		slog.Error("load API configuration", "error", err)
		return 2
	}
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()
	if err := run(ctx, value); err != nil && !errors.Is(err, context.Canceled) {
		slog.Error("API service stopped", "error", err)
		return 1
	}
	return 0
}

func loadConfig(path string) (config, error) {
	value, err := decodeConfig(path)
	if err != nil {
		return config{}, err
	}
	if value.Listen == "" {
		value.Listen = "127.0.0.1:8080"
	}
	if err := validateListen(value.Listen); err != nil {
		return config{}, err
	}
	if err := validateConfig(value); err != nil {
		return config{}, err
	}
	return value, nil
}

func decodeConfig(path string) (config, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return config{}, errors.New("config path must be clean and absolute")
	}
	file, err := os.Open(path)
	if err != nil {
		return config{}, err
	}
	defer file.Close()
	decoder := json.NewDecoder(io.LimitReader(file, 1<<20))
	decoder.DisallowUnknownFields()
	var value config
	if err := decoder.Decode(&value); err != nil {
		return config{}, err
	}
	var trailing any
	if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
		return config{}, errors.New("configuration has trailing content")
	}
	return value, nil
}

func validateListen(listen string) error {
	host, _, err := net.SplitHostPort(listen)
	if err != nil {
		return errors.New("listen must include host and port")
	}
	ip := net.ParseIP(host)
	if ip == nil || !ip.IsLoopback() {
		return errors.New("API listen address must be loopback")
	}
	return nil
}

func validateConfig(value config) error {
	if value.DatabaseURL == "" || !filepath.IsAbs(value.ArtifactRoot) ||
		filepath.Clean(value.ArtifactRoot) != value.ArtifactRoot ||
		!filepath.IsAbs(value.RepositoryRoot) ||
		filepath.Clean(value.RepositoryRoot) != value.RepositoryRoot {
		return errors.New("incomplete API configuration")
	}
	if err := value.Policy.Validate(); err != nil || value.Policy.Repository.Root != value.RepositoryRoot {
		return errors.New("invalid or mismatched beta policy")
	}
	if value.Publication != nil && (value.Publication.RepositoryRoot != value.Policy.Repository.Root ||
		value.Publication.RepositoryOwner != value.Policy.Repository.Owner ||
		value.Publication.RepositoryName != value.Policy.Repository.Name ||
		value.Publication.Remote != value.Policy.Repository.Remote ||
		value.Publication.BaseBranch != value.Policy.Repository.BaseBranch) {
		return errors.New("publication configuration does not match beta policy")
	}
	return nil
}

func run(ctx context.Context, value config) error {
	migrateCtx, cancelMigrate := context.WithTimeout(ctx, 30*time.Second)
	err := workflow.Migrate(migrateCtx, value.DatabaseURL)
	if err == nil {
		err = approval.Migrate(migrateCtx, value.DatabaseURL)
	}
	if err == nil {
		err = publication.Migrate(migrateCtx, value.DatabaseURL)
	}
	cancelMigrate()
	if err != nil {
		return fmt.Errorf("migrate workflow: %w", err)
	}
	pool, err := pgxpool.New(ctx, value.DatabaseURL)
	if err != nil {
		return err
	}
	defer pool.Close()
	pingCtx, cancelPing := context.WithTimeout(ctx, 30*time.Second)
	err = pool.Ping(pingCtx)
	cancelPing()
	if err != nil {
		return err
	}
	artifacts, err := artifact.NewStore(value.ArtifactRoot, value.MaxArtifactBytes)
	if err != nil {
		return err
	}
	defer artifacts.Close()
	approvalLedger, err := approval.NewPostgresApprovalRepository(pool)
	if err != nil {
		return err
	}
	approvalService, err := approval.NewService(artifacts, workflow.NewStore(pool), approvalLedger)
	if err != nil {
		return err
	}
	publicationService, err := buildPublication(value.Publication, artifacts, pool)
	if err != nil {
		return err
	}
	workflowStore := workflow.NewStore(pool)
	runIntake, err := controlapi.NewRunIntakeCoordinator(
		pool, workflowStore, artifacts, value.RepositoryRoot, value.Policy,
	)
	if err != nil {
		return err
	}
	handler, err := controlapi.New(controlapi.Config{
		Principals: value.Principals, ServiceActorID: value.ServiceActorID,
		MaxBodyBytes:  value.MaxBodyBytes,
		TrustedChecks: value.TrustedChecks,
		Policy:        value.Policy,
	}, workflowStore, runtime.NewLedger(pool), runIntake, artifacts,
		runtime.NewBindingRepository(pool), approvalService, publicationService, slog.Default())
	if err != nil {
		return err
	}
	server := &http.Server{
		Addr: value.Listen, Handler: handler.Handler(),
		ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 30 * time.Second,
		WriteTimeout: 30 * time.Second, IdleTimeout: time.Minute,
	}
	errs := make(chan error, 1)
	go func() {
		slog.Info("API service ready", "listen", value.Listen)
		errs <- server.ListenAndServe()
	}()
	select {
	case <-ctx.Done():
		shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		return server.Shutdown(shutdown)
	case err := <-errs:
		if errors.Is(err, http.ErrServerClosed) {
			return nil
		}
		return err
	}
}

func buildPublication(
	value *publicationConfig, artifacts *artifact.Store, pool *pgxpool.Pool,
) (*publication.Service, error) {
	if value == nil {
		return nil, nil
	}
	gitPublisher, err := publication.NewGitCommandPublisher(
		value.RepositoryRoot, value.Remote, value.BaseBranch,
	)
	if err != nil {
		return nil, err
	}
	credential, err := publication.NewFileCredential(value.TokenFile)
	if err != nil {
		return nil, err
	}
	pulls, err := publication.NewGitHubRESTClient(
		value.APIEndpoint, value.APIVersion, publication.DefaultMaxBodyBytes,
		publication.DefaultTimeout, credential,
	)
	if err != nil {
		return nil, err
	}
	ledger, err := publication.NewPostgresPublicationRepository(pool)
	if err != nil {
		return nil, err
	}
	return publication.NewService(publication.Config{
		RepositoryRoot: value.RepositoryRoot, RepositoryOwner: value.RepositoryOwner,
		RepositoryName: value.RepositoryName, Remote: value.Remote,
		BaseBranch: value.BaseBranch, BranchPrefix: value.BranchPrefix,
		ActorID: value.ActorID, APIEndpoint: value.APIEndpoint,
		APIVersion: value.APIVersion,
	}, artifact.Publication{Store: artifacts}, workflow.NewStore(pool),
		gitPublisher, pulls, ledger)
}
CREATE TABLE draft_pull_request_publications (
    publication_id text PRIMARY KEY,
    request_digest text NOT NULL CHECK (request_digest ~ '^[a-f0-9]{64}$'),
    requested_at timestamptz NOT NULL,
    repository text NOT NULL,
    base_branch text NOT NULL,
    head_branch text NOT NULL,
    base_commit text NOT NULL CHECK (base_commit ~ '^[a-f0-9]{40}$'),
    candidate_commit text NOT NULL CHECK (candidate_commit ~ '^[a-f0-9]{40}$'),
    specification_digest text NOT NULL CHECK (specification_digest ~ '^[a-f0-9]{64}$'),
    implementation_digest text NOT NULL CHECK (implementation_digest ~ '^[a-f0-9]{64}$'),
    execution_digest text NOT NULL CHECK (execution_digest ~ '^[a-f0-9]{64}$'),
    verification_digest text NOT NULL CHECK (verification_digest ~ '^[a-f0-9]{64}$'),
    review_digest text NOT NULL CHECK (review_digest ~ '^[a-f0-9]{64}$'),
    approval_digest text NOT NULL CHECK (approval_digest ~ '^[a-f0-9]{64}$'),
    expected_run_revision bigint NOT NULL CHECK (expected_run_revision > 0),
    state text NOT NULL CHECK (state IN ('reserved', 'branch_ready', 'pr_ready', 'completed')),
    published_branch text,
    published_candidate_commit text CHECK (published_candidate_commit ~ '^[a-f0-9]{40}$'),
    pull_request_number bigint CHECK (pull_request_number > 0),
    pull_request_url text,
    publication_artifact_uri text,
    publication_artifact_digest text CHECK (publication_artifact_digest ~ '^[a-f0-9]{64}$'),
    completed_at timestamptz,
    CHECK (
        (state = 'reserved' AND published_branch IS NULL AND published_candidate_commit IS NULL
            AND pull_request_number IS NULL AND pull_request_url IS NULL
            AND publication_artifact_uri IS NULL AND publication_artifact_digest IS NULL
            AND completed_at IS NULL)
        OR
        (state = 'branch_ready' AND published_branch IS NOT NULL
            AND published_candidate_commit IS NOT NULL AND pull_request_number IS NULL
            AND pull_request_url IS NULL AND publication_artifact_uri IS NULL
            AND publication_artifact_digest IS NULL AND completed_at IS NULL)
        OR
        (state = 'pr_ready' AND published_branch IS NOT NULL
            AND published_candidate_commit IS NOT NULL AND pull_request_number IS NOT NULL
            AND pull_request_url IS NOT NULL AND publication_artifact_uri IS NULL
            AND publication_artifact_digest IS NULL AND completed_at IS NULL)
        OR
        (state = 'completed' AND published_branch IS NOT NULL
            AND published_candidate_commit IS NOT NULL AND pull_request_number IS NOT NULL
            AND pull_request_url IS NOT NULL AND publication_artifact_uri IS NOT NULL
            AND publication_artifact_digest IS NOT NULL AND completed_at IS NOT NULL)
    )
);

CREATE FUNCTION protect_draft_pull_request_publication()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.state = 'reserved' THEN
            RETURN OLD;
        END IF;
        RAISE EXCEPTION 'checkpointed publications are immutable';
    END IF;
    IF NEW.publication_id <> OLD.publication_id
        OR NEW.request_digest <> OLD.request_digest
        OR NEW.requested_at <> OLD.requested_at
        OR NEW.repository <> OLD.repository
        OR NEW.base_branch <> OLD.base_branch
        OR NEW.head_branch <> OLD.head_branch
        OR NEW.base_commit <> OLD.base_commit
        OR NEW.candidate_commit <> OLD.candidate_commit
        OR NEW.specification_digest <> OLD.specification_digest
        OR NEW.implementation_digest <> OLD.implementation_digest
        OR NEW.execution_digest <> OLD.execution_digest
        OR NEW.verification_digest <> OLD.verification_digest
        OR NEW.review_digest <> OLD.review_digest
        OR NEW.approval_digest <> OLD.approval_digest
        OR NEW.expected_run_revision <> OLD.expected_run_revision THEN
        RAISE EXCEPTION 'publication identity and evidence are immutable';
    END IF;
    IF OLD.state = 'reserved' AND NEW.state = 'branch_ready' THEN
        RETURN NEW;
    END IF;
    IF OLD.state = 'branch_ready' AND NEW.state = 'pr_ready'
        AND NEW.published_branch = OLD.published_branch
        AND NEW.published_candidate_commit = OLD.published_candidate_commit THEN
        RETURN NEW;
    END IF;
    IF OLD.state = 'pr_ready' AND NEW.state = 'completed'
        AND NEW.published_branch = OLD.published_branch
        AND NEW.published_candidate_commit = OLD.published_candidate_commit
        AND NEW.pull_request_number = OLD.pull_request_number
        AND NEW.pull_request_url = OLD.pull_request_url THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'publication checkpoints and completed rows are immutable';
END;
$$;

CREATE TRIGGER draft_pull_request_publications_immutable
BEFORE UPDATE OR DELETE ON draft_pull_request_publications
FOR EACH ROW EXECUTE FUNCTION protect_draft_pull_request_publication();
