	runGit(t, root, "add", "add.go")
	runGit(t, root, "commit", "-m", "base")
	runGit(t, root, "remote", "add", "origin", remote)
	runGit(t, root, "push", "origin", "main:main")
	if err := os.WriteFile(filepath.Join(root, "add.go"), []byte("candidate"), 0o600); err != nil {
		t.Fatal(err)
